import torch, json
ids=json.load(open('/work/cats.json'))
LM=W('lm_head.weight'); nw=W('model.language_model.norm.weight')
g=LM[:150000:37].mean(0)
D={}
for k,t in ids.items():
    d=(LM[t].mean(0)-g)*nw
    D[k]=d/d.norm()
keys=list(D); M=torch.stack([D[k] for k in keys])  # C x 4096
res=[]
for L in range(10,32):
    Wd=W(f'model.language_model.layers.{L}.mlp.down_proj.weight')  # 4096 x 12288
    Wn=Wd/Wd.norm(dim=0,keepdim=True)
    C=M@Wn  # C x 12288
    for ci,k in enumerate(keys):
        for sgn in (1,-1):
            c=sgn*C[ci]
            v,i=c.topk(2)
            for vv,ii in zip(v,i):
                others=torch.cat([C[:ci,ii],C[ci+1:,ii]])*sgn
                res.append((vv.item(),L,int(ii),k,sgn,others.max().item()))
res.sort(reverse=True)
json.dump(res,open('/work/res.json','w'))
best={}
for r in res:
    best.setdefault(r[3],[]).append(r)
for k in keys:
    print(k,[(round(a,3),L,i,s,round(o,2)) for a,L,i,_,s,o in best[k][:5]])

